//! `yate skill`: instructions for AI agents that configure yate, and
//! `yate skill --init`, which installs them as an agent skill (`/yate`).
//!
//! The skill goes to the git root found from the working directory up to the
//! home directory, so the agent sees it in every folder of the repository.
//! Outside a repository it goes to the home directory, for every project.
//! `yate update` rewrites the skills that still have the `Generated by` line.

use std::path::{Path, PathBuf};

const SKILL: &str = include_str!("SKILL.md");
const AGENT_INSTRUCTIONS: &str = include_str!("agent-instructions.txt");
const CONFIGURATION: &str = include_str!("../../docs/configuration.md");
const PLUGINS: &str = include_str!("../../docs/plugins.md");
const SKILL_NAME: &str = "yate";
const SKILL_DIRS: [(&str, &str); 2] = [
    (".agents/skills", "Codex, Cursor"),
    (".claude/skills", "Claude Code, Cursor"),
];

/// What `yate skill` prints: a preamble for agents, the `yate.json` and
/// plugin references, and the template with every setting and its default.
pub fn instructions() -> String {
    format!(
        "{AGENT_INSTRUCTIONS}\n{CONFIGURATION}\n{PLUGINS}\n# Every setting with its default (yate init)\n\n```jsonc\n{}```\n",
        crate::settings::template()
    )
}

/// Marks a skill file written by `yate skill --init`. `yate update` rewrites
/// only the files that still have it.
const MARKER: &str = "<!-- Generated by `yate skill --init`";

/// The skill with the marker line right after the front matter, where the
/// agents still read the front matter.
fn generated_skill() -> String {
    let marker = format!(
        "{MARKER}. `yate update` rewrites this file; delete this line to keep your own changes. -->\n"
    );
    match SKILL
        .strip_prefix("---\n")
        .and_then(|rest| rest.find("\n---\n"))
    {
        Some(end) => {
            let split = "---\n".len() + end + "\n---\n".len();
            format!("{}{marker}{}", &SKILL[..split], &SKILL[split..])
        }
        None => format!("{marker}{SKILL}"),
    }
}

fn is_generated(text: &str) -> bool {
    text.lines().any(|line| line.starts_with(MARKER))
}

fn write_file(file: &Path, content: &str) -> Result<(), String> {
    if let Some(parent) = file.parent() {
        std::fs::create_dir_all(parent).map_err(|err| format!("{}: {err}", parent.display()))?;
    }
    std::fs::write(file, content).map_err(|err| format!("{}: {err}", file.display()))
}

fn skill_files(root: &Path) -> Vec<PathBuf> {
    SKILL_DIRS
        .iter()
        .map(|(dir, _)| root.join(dir).join(SKILL_NAME).join("SKILL.md"))
        .collect()
}

/// Writes the skill for `yate skill --init`, replacing the files when they
/// exist, and returns the lines to print.
pub fn init(cwd: &Path, home: Option<&Path>) -> Result<Vec<String>, String> {
    let (root, in_repository) = match git_root(cwd, home) {
        Some(root) => (root, true),
        None => (
            home.ok_or("not in a git repository and the home directory is unknown (set HOME)")?
                .to_path_buf(),
            false,
        ),
    };
    let content = generated_skill();
    let mut lines = vec![if in_repository {
        format!("Project root: {} (git root)", root.display())
    } else {
        format!(
            "Not in a git repository: installed for all projects in {}",
            root.display()
        )
    }];
    for ((dir, read_by), file) in SKILL_DIRS.iter().zip(skill_files(&root)) {
        let action = if file.exists() { "Updated" } else { "Created" };
        write_file(&file, &content)?;
        let path = Path::new(dir).join(SKILL_NAME).join("SKILL.md");
        lines.push(format!("{action} {}  ({read_by})", path.display()));
    }
    lines.push(String::new());
    lines.push("Try: /yate use the gruvbox-dark theme and a tab size of 4".to_string());
    Ok(lines)
}

/// The skill files under `root` that still have the marker.
fn generated_files(root: &Path) -> Vec<PathBuf> {
    skill_files(root)
        .into_iter()
        .filter(|file| std::fs::read_to_string(file).is_ok_and(|text| is_generated(&text)))
        .collect()
}

/// Rewrites the skills that `yate skill --init` wrote, when they still have
/// the marker: the ones at the git root of `cwd`, else (no repository, or no
/// generated skill in it) the ones in the home directory. Returns the lines
/// to print: the files it changed. `yate update` runs it with the new binary
/// (`yate skill --refresh`), so the new skill text is written.
pub fn refresh(cwd: &Path, home: Option<&Path>) -> Vec<String> {
    let files = git_root(cwd, home)
        .map(|root| generated_files(&root))
        .filter(|files| !files.is_empty())
        .or_else(|| home.map(generated_files))
        .unwrap_or_default();

    let content = generated_skill();
    let mut updated = Vec::new();
    let mut errors = Vec::new();
    for file in files {
        if std::fs::read_to_string(&file).is_ok_and(|text| text == content) {
            continue;
        }
        match write_file(&file, &content) {
            Ok(()) => updated.push(format!("  {}", file.display())),
            Err(err) => errors.push(format!("Failed to update the skill {err}")),
        }
    }
    let mut lines = Vec::new();
    if !updated.is_empty() {
        lines.push("Updated skills:".to_string());
        lines.extend(updated);
    }
    lines.extend(errors);
    lines
}

fn git_root(cwd: &Path, home: Option<&Path>) -> Option<PathBuf> {
    let mut dir = cwd;
    loop {
        if dir.join(".git").exists() {
            return Some(dir.to_path_buf());
        }
        if Some(dir) == home {
            return None;
        }
        dir = dir.parent()?;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn temp_dir(name: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!("yate-skill-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn instructions_hold_the_references_and_the_template() {
        let text = instructions();
        assert!(text.starts_with("yate - instructions for AI agents"));
        assert!(text.contains("# Configuration: yate.json"));
        assert!(text.contains("# Plugins and configuration"));
        assert!(text.contains(&crate::settings::template()));
    }

    #[test]
    fn init_writes_the_skill_at_the_git_root() {
        let home = temp_dir("repo");
        let repo = home.join("code/app");
        let nested = repo.join("src/lib");
        std::fs::create_dir_all(repo.join(".git")).unwrap();
        std::fs::create_dir_all(&nested).unwrap();

        let lines = init(&nested, Some(&home)).unwrap();
        assert_eq!(
            lines[0],
            format!("Project root: {} (git root)", repo.display())
        );
        assert_eq!(
            lines[1],
            "Created .agents/skills/yate/SKILL.md  (Codex, Cursor)"
        );
        for dir in [".agents/skills", ".claude/skills"] {
            let skill = std::fs::read_to_string(repo.join(dir).join("yate/SKILL.md")).unwrap();
            assert_eq!(skill, generated_skill());
        }
        assert!(generated_skill().contains("\n---\n<!-- Generated by `yate skill --init`. "));
        assert!(!nested.join(".claude").exists());
        assert!(!home.join(".claude").exists());

        std::fs::write(repo.join(".claude/skills/yate/SKILL.md"), "edited").unwrap();
        let lines = init(&repo, Some(&home)).unwrap();
        assert_eq!(
            lines[1],
            "Updated .agents/skills/yate/SKILL.md  (Codex, Cursor)"
        );
        assert_eq!(
            std::fs::read_to_string(repo.join(".claude/skills/yate/SKILL.md")).unwrap(),
            generated_skill()
        );
        std::fs::remove_dir_all(&home).unwrap();
    }

    #[test]
    fn init_outside_a_repository_writes_the_skill_to_the_home_directory() {
        let home = temp_dir("home");
        let notes = home.join("notes");
        std::fs::create_dir_all(&notes).unwrap();

        let lines = init(&notes, Some(&home)).unwrap();
        assert!(lines[0].starts_with("Not in a git repository"));
        assert!(home.join(".agents/skills/yate/SKILL.md").exists());
        assert!(home.join(".claude/skills/yate/SKILL.md").exists());
        assert!(!notes.join(".claude").exists());
        std::fs::remove_dir_all(&home).unwrap();
    }

    #[test]
    fn refresh_rewrites_the_generated_skills() {
        let home = temp_dir("refresh");
        let repo = home.join("repo");
        let empty = home.join("empty");
        let other = home.join("other");
        for dir in [&repo, &empty, &other] {
            std::fs::create_dir_all(dir.join(".git")).unwrap();
        }
        for cwd in [&repo, &other, &home] {
            init(cwd, Some(&home)).unwrap();
        }
        let marker = generated_skill()
            .lines()
            .find(|line| line.starts_with(MARKER))
            .unwrap()
            .to_string();
        let stale = format!("---\nname: yate\n---\n{marker}\nold\n");
        let claude = |root: &Path| root.join(".claude/skills/yate/SKILL.md");
        for root in [&repo, &other, &home] {
            std::fs::write(claude(root), &stale).unwrap();
        }
        let own = repo.join(".agents/skills/yate/SKILL.md");
        std::fs::write(&own, "my own skill").unwrap();
        let read = |file: &Path| std::fs::read_to_string(file).unwrap();
        let listed = |root: &Path| {
            vec![
                "Updated skills:".to_string(),
                format!("  {}", claude(root).display()),
            ]
        };

        // In a repository with the skill: only that skill.
        assert_eq!(refresh(&repo.join("src"), Some(&home)), listed(&repo));
        assert_eq!(read(&claude(&repo)), generated_skill());
        assert_eq!(read(&own), "my own skill");
        assert_eq!(read(&claude(&home)), stale);

        // In a repository without the skill: the skill in the home directory.
        assert_eq!(refresh(&empty, Some(&home)), listed(&home));
        assert_eq!(read(&claude(&other)), stale);
        assert!(refresh(&home, Some(&home)).is_empty());
        std::fs::remove_dir_all(&home).unwrap();
    }

    #[test]
    fn the_skill_names_itself_yate() {
        assert!(SKILL.starts_with("---\nname: yate\ndescription: "));
    }
}
